//www.statmuse.com/nfl/ask/tennessee-titans-game-log-2024-including-passing-yards-rushing-yards-turnovers-first-downs-time-of-possession\",\"statmusePlayoffs\":\"https://www.statmuse.com/nfl/ask/tennessee-titans-playoff-game-log-2024\",\"statmuseStatsAsk\":\"\",\"espnSchedule\":{\"url\":\"https://www.espn.com/nfl/team/schedule/_/name/ten/season/2024\",\"status\":\"deferred\"},\"pfrTeam\":{\"url\":\"https://www.pro-football-reference.com/teams/oti/2024.htm\",\"status\":\"deferred\"}}},\"2025\":{\"team_name\":\"Tennessee Titans\",\"record\":\"3-14\",\"wins\":3,\"losses\":14,\"ties\":0,\"division\":\"AFC South\",\"division_rank\":4,\"division_finish\":\"4 of 4\",\"playoff_result\":\"Missed playoffs\",\"notable_season\":false,\"stats\":{\"GP\":17,\"PTS\":284,\"YDS\":4413,\"PLY\":1004,\"AVG\":4.4,\"RUSH YDS\":1589,\"RUSH ATT\":378,\"RUSH AVG\":4.2,\"PASS YDS\":3241,\"PASS ATT\":570,\"PASS AVG\":5.7,\"SCK\":56,\"SCKY\":417,\"1DWN\":261,\"RUSH 1DWN\":85,\"PASS 1DWN\":156,\"PEN 1DWN\":20,\"PEN\":130,\"PEN YDS\":1011},\"standings\":[{\"team\":\"Jaguars\",\"W\":13,\"L\":4,\"T\":0,\"PCT\":0.765},{\"team\":\"Texans\",\"W\":12,\"L\":5,\"T\":0,\"PCT\":0.706},{\"team\":\"Colts\",\"W\":8,\"L\":9,\"T\":0,\"PCT\":0.471},{\"team\":\"Titans\",\"W\":3,\"L\":14,\"T\":0,\"PCT\":0.176}],\"leaders\":[{\"metric\":\"PASS YDS\",\"value\":\"3,169\",\"name\":\"Ward\"},{\"metric\":\"RUSH YDS\",\"value\":\"1,082\",\"name\":\"Pollard\"},{\"metric\":\"REC YDS\",\"value\":\"560\",\"name\":\"Okonkwo\"}],\"inactive\":false,\"source_unavailable\":false,\"sources\":{\"statmuseTeam\":\"https://www.statmuse.com/nfl/team/2025-tennessee-titans-72/2025\",\"statmuseGameLog\":\"https://www.statmuse.com/nfl/ask/tennessee-titans-game-log-2025-including-passing-yards-rushing-yards-turnovers-first-downs-time-of-possession\",\"statmusePlayoffs\":\"https://www.statmuse.com/nfl/ask/tennessee-titans-playoff-game-log-2025\",\"statmuseStatsAsk\":\"\",\"espnSchedule\":{\"url\":\"https://www.espn.com/nfl/team/schedule/_/name/ten/season/2025\",\"status\":\"deferred\"},\"pfrTeam\":{\"url\":\"https://www.pro-football-reference.com/teams/oti/2025.htm\",\"status\":\"deferred\"}}}};\n\nfunction getYoutubeSummaryUrl(game, seasonYear) {\n  if (!game) return '';\n  const uniqueKey = [game.year || seasonYear || '', game.round || game.week || '', game.opponent || '', game.location || '', `${game.ravensScore ?? ''}-${game.oppScore ?? ''}`].join(\"|\");\n  if (typeof RAVENS_HIGHLIGHT_LINKS !== 'undefined' && RAVENS_HIGHLIGHT_LINKS[uniqueKey] && RAVENS_HIGHLIGHT_LINKS[uniqueKey].url) {\n    return RAVENS_HIGHLIGHT_LINKS[uniqueKey].url;\n  }\n  return game.youtubeSummaryUrl || game.youtubeUrl || '';\n}\n\nconst YEARS = [...new Set([...ALL_GAMES.map(g => g.year), ...Object.keys(SEASON_EXTRA_DATA).map(Number)])].sort((a,b) => a-b);\nconst seasons = {};\n\nALL_GAMES.forEach((g, index) => {\n  const key = String(g.year);\n  if (!seasons[key]) seasons[key] = [];\n  seasons[key].push({ ...g, _index: index });\n});\n\nlet state = {\n  selectedYear: String(YEARS[YEARS.length - 1]),\n  filterMode: 'all',\n  search: '',\n  selectedMatchIndex: null,\n  selectedPlayer: null,\n  selectedOpponent: null,\n  playerPromptMode: 'star',\n  isHistorical: false\n};\n\nfunction escapeHtml(str) {\n  return String(str)\n    .replaceAll('&', '&amp;')\n    .replaceAll('<', '&lt;')\n    .replaceAll('>', '&gt;')\n    .replaceAll('\"', '&quot;')\n    .replaceAll(\"'\", '&#039;');\n}\n\nfunction currentTeamLabel() {\n  if (typeof TEAM_CONFIG === 'undefined' || !TEAM_CONFIG) return 'this team';\n  return TEAM_CONFIG.teamName || TEAM_CONFIG.fullName || TEAM_CONFIG.shortName || 'this team';\n}\n\nfunction syncViewToggleUI() {\n  document.querySelectorAll('.toggle').forEach((btn) => {\n    btn.classList.toggle('active', btn.dataset.view === state.filterMode);\n  });\n}\n\nfunction syncSearchInputUI() {\n  const input = document.getElementById('seasonSearch');\n  if (input) input.value = state.search || '';\n}\n\nfunction emptyStateHTML({ kicker, title, description, actions = [] }) {\n  return `\n    <div class=\"empty empty-card\">\n      <div class=\"empty-kicker\">${escapeHtml(kicker || 'No results')}</div>\n      <strong>${escapeHtml(title || 'Nothing matched.')}</strong>\n      <p>${escapeHtml(description || 'Try a broader search or change the current filter.')}</p>\n      ${actions.length ? `<div class=\"empty-actions\">${actions.map((action) => `<button type=\"button\" class=\"empty-btn\" data-empty-action=\"${escapeHtml(action.action)}\">${escapeHtml(action.label)}</button>`).join('')}</div>` : ''}\n    </div>\n  `;\n}\n\nfunction handleEmptyStateAction(action) {\n  if (!action) return;\n  if (action === 'clear-search') {\n    state.search = '';\n    syncSearchInputUI();\n  }\n  if (action === 'show-all-games') {\n    state.filterMode = 'all';\n    syncViewToggleUI();\n  }\n  if (action === 'latest-season') {\n    state.search = '';\n    state.filterMode = 'all';\n    state.selectedYear = String(YEARS[YEARS.length - 1]);\n    syncSearchInputUI();\n    syncViewToggleUI();\n  }\n  state.selectedMatchIndex = null;\n  render();\n}\n\nfunction timelineTooltipText(game) {\n  if (!game) return '';\n  const resultLabel = game.result === 'W' ? 'Win' : game.result === 'L' ? 'Loss' : 'Tie';\n  return [\n    game.year,\n    game.round,\n    `vs ${game.opponent}`,\n    `${game.ravensScore}-${game.oppScore}`,\n    resultLabel\n  ].filter(Boolean).join(' | ');\n}\n\nfunction isTypingTarget(target) {\n  if (!target) return false;\n  const tag = String(target.tagName || '').toLowerCase();\n  return target.isContentEditable || tag === 'input' || tag === 'textarea' || tag === 'select';\n}\n\nfunction seasonSummary(year) {\n  const games = seasons[year] || [];\n  const regular = games.filter(g => !g.isPlayoff);\n  const playoffs = games.filter(g => g.isPlayoff);\n  const bucket = (arr) => {\n    const w = arr.filter(g => g.result === 'W').length;\n    const l = arr.filter(g => g.result === 'L').length;\n    const t = arr.filter(g => g.result === 'T').length;\n    const pf = arr.reduce((s,g) => s + g.ravensScore, 0);\n    const pa = arr.reduce((s,g) => s + g.oppScore, 0);\n    return { w, l, t, pf, pa, games: arr.length };\n  };\n  const reg = bucket(regular);\n  const post = bucket(playoffs);\n  const all = bucket(games);\n  return {\n    reg, post, all,\n    winPct: all.games ? ((all.w / all.games) * 100).toFixed(1) : '0.0',\n    pointDiff: all.pf - all.pa\n  };\n}\n\n\nfunction seasonGames(year) {\n  return [...(seasons[String(year)] || [])];\n}\n\nfunction seasonCoach(year) {\n  return TEAM_CONFIG.headCoach || '—';\n}\n\n\nfunction seasonOutcomeLabel(year) {\n  const games = seasonGames(year);\n  const playoffs = games.filter(g => g.isPlayoff);\n  if (!playoffs.length) return 'Missed playoffs';\n  const finalRound = playoffs[playoffs.length - 1]?.round || '';\n  if (/super bowl/i.test(finalRound) && playoffs[playoffs.length - 1].result === 'W') return 'Super Bowl Champions';\n  if (/super bowl/i.test(finalRound) && playoffs[playoffs.length - 1].result === 'L') return 'Super Bowl appearance';\n  if (/conference championship/i.test(finalRound)) return 'Conference Championship';\n  if (/divisional/i.test(finalRound)) return 'Divisional Round';\n  if (/wild card/i.test(finalRound)) return 'Wild Card Round';\n  return 'Playoff team';\n}\n\nfunction winLossTimelineHTML(games) {\n  if (!games.length) return '<div class=\"panel-note\">No timeline for this selection yet.</div>';\n  return `\n    <div class=\"timeline-legend\">\n      <span class=\"leg-win\">Win</span>\n      <span class=\"leg-loss\">Loss</span>\n      <span class=\"leg-tie\">Tie</span>\n      <span class=\"leg-playoff\">Playoff game</span>\n    </div>\n    <div class=\"timeline-bar\">\n      ${games.map(g => {\n        const tip = timelineTooltipText(g);\n        return `<div class=\"timeline-pill ${g.result === 'W' ? 'win' : g.result === 'L' ? 'loss' : 'tie'} ${g.isPlayoff ? 'playoff' : ''}\" data-tip=\"${escapeHtml(tip)}\" title=\"${escapeHtml(tip)}\" aria-label=\"${escapeHtml(tip)}\"></div>`;\n      }).join('')}\n    </div>\n  `;\n}\n\nfunction playoffBracketHTML(year) {\n  const games = seasonGames(year).filter(g => g.isPlayoff);\n  if (!games.length) return '<div class=\"panel-note\"></div>';\n  return `<div class=\"playoff-bracket\">\n    ${games.map(g => `<div class=\"bracket-step ${g.result === 'W' ? 'win' : ''}\">\n      <div>\n        <span>${g.round}</span>\n        <strong>Ravens ${g.ravensScore} – ${g.oppScore} ${g.opponent}</strong>\n      </div>\n      <div class=\"${g.result === 'W' ? 'green' : g.result === 'L' ? 'red' : 'muted'}\"><strong>${g.result}</strong></div>\n    </div>`).join('')}\n  </div>`;\n}\n\nfunction getFranchiseRecords() {\n  const summaries = YEARS.map(y => ({ year: String(y), sum: seasonSummary(String(y)), games: seasonGames(String(y)) }));\n  const byPF = [...summaries].sort((a,b) => b.sum.all.pf - a.sum.all.pf)[0];\n  const byPA = [...summaries].sort((a,b) => a.sum.all.pa - b.sum.all.pa)[0];\n  const byWinPct = [...summaries].sort((a,b) => Number(b.sum.winPct) - Number(a.sum.winPct))[0];\n  const byLossPct = [...summaries].sort((a,b) => Number(a.sum.winPct) - Number(b.sum.winPct))[0];\n  const byPointDiff = [...summaries].sort((a,b) => b.sum.pointDiff - a.sum.pointDiff)[0];\n  let biggestWin = null;\n  let worstLoss = null;\n  ALL_GAMES.forEach(g => {\n    const margin = g.ravensScore - g.oppScore;\n    if (!biggestWin || margin > biggestWin.margin) biggestWin = { g, margin };\n    if (!worstLoss || margin < worstLoss.margin) worstLoss = { g, margin };\n  });\n\n  let longestWin = {len:0, year:null}, longestLoss = {len:0, year:null};\n  YEARS.forEach(y => {\n    const games = seasonGames(String(y));\n    let w=0,l=0;\n    games.forEach(g => {\n      if (g.result === 'W') { w += 1; l = 0; }\n      else if (g.result === 'L') { l += 1; w = 0; }\n      else { w = 0; l = 0; }\n      if (w > longestWin.len) longestWin = {len:w, year:String(y)};\n      if (l > longestLoss.len) longestLoss = {len:l, year:String(y)};\n    });\n  });\n  return {byPF, byPA, byWinPct, byLossPct, byPointDiff, biggestWin, worstLoss, longestWin, longestLoss};\n}\n\nfunction franchiseTimelineData() {\n  return TIMELINE_COPY;\n}\n\n\nfunction renderFranchiseInsights() {\n  const recordsHost = document.getElementById('franchiseRecords');\n  const timelineHost = document.getElementById('franchiseTimeline');\n  const oppHost = document.getElementById('franchiseOpponents');\n  if (!recordsHost || !timelineHost || !oppHost) return;\n\n  const records = getFranchiseRecords();\n  recordsHost.innerHTML = `\n    <div class=\"record-grid\">\n      <div class=\"record-card\"><span>Best Win % Season</span><strong>${records.byWinPct.year} • ${records.byWinPct.sum.reg.w}-${records.byWinPct.sum.reg.l}${records.byWinPct.sum.reg.t ? '-' + records.byWinPct.sum.reg.t : ''} (${records.byWinPct.sum.winPct}%)</strong></div>\n      <div class=\"record-card\"><span>Lowest Win % Season</span><strong>${records.byLossPct.year} • ${records.byLossPct.sum.reg.w}-${records.byLossPct.sum.reg.l}${records.byLossPct.sum.reg.t ? '-' + records.byLossPct.sum.reg.t : ''} (${records.byLossPct.sum.winPct}%)</strong></div>\n      <div class=\"record-card\"><span>Most Points Scored</span><strong>${records.byPF.year} • ${records.byPF.sum.all.pf} points</strong></div>\n      <div class=\"record-card\"><span>Fewest Points Allowed</span><strong>${records.byPA.year} • ${records.byPA.sum.all.pa} allowed</strong></div>\n      <div class=\"record-card\"><span>Best Point Differential</span><strong>${records.byPointDiff.year} • ${records.byPointDiff.sum.pointDiff > 0 ? '+' : ''}${records.byPointDiff.sum.pointDiff}</strong></div>\n      <div class=\"record-card\"><span>Biggest Win</span><strong>${records.biggestWin.g.year} ${records.biggestWin.g.round} vs ${records.biggestWin.g.opponent} • +${records.biggestWin.margin}</strong></div>\n      <div class=\"record-card\"><span>Worst Loss</span><strong>${records.worstLoss.g.year} ${records.worstLoss.g.round} vs ${records.worstLoss.g.opponent} • ${records.worstLoss.margin}</strong></div>\n      <div class=\"record-card\"><span>Longest Win Streak</span><strong>${records.longestWin.len} straight • ${records.longestWin.year}</strong></div>\n      <div class=\"record-card\"><span>Longest Loss Streak</span><strong>${records.longestLoss.len} straight • ${records.longestLoss.year}</strong></div>\n    </div>\n  `;\n\n  timelineHost.innerHTML = `<div class=\"timeline-list\">\n    ${franchiseTimelineData().map(item => `<div class=\"timeline-item\">\n      <div class=\"timeline-year\">${item.year}</div>\n      <div class=\"timeline-copy\"><strong>${item.title}</strong><span>${item.note}</span></div>\n    </div>`).join('')}\n  </div>`;\n\n  const teams = {};\n  ALL_GAMES.forEach(g => {\n    if (g.opponent === 'Ravens') return;\n    teams[g.opponent] ??= {team:g.opponent,w:0,l:0,t:0,pf:0,pa:0,games:0};\n    teams[g.opponent].games += 1;\n    teams[g.opponent].pf += g.ravensScore;\n    teams[g.opponent].pa += g.oppScore;\n    if (g.result === 'W') teams[g.opponent].w += 1;\n    else if (g.result === 'L') teams[g.opponent].l += 1;\n    else teams[g.opponent].t += 1;\n  });\n  const topOpps = Object.values(teams).sort((a,b) => b.games - a.games).slice(0,10);\n  oppHost.innerHTML = `<div class=\"opp-table-mini table-wrap\"><table>\n    <thead><tr><th>Opponent</th><th>Record</th><th>Games</th><th>Win %</th><th>Points</th></tr></thead>\n    <tbody>\n      ${topOpps.map(t => {\n        const pct = (((t.w + t.t*0.5) / t.games) * 100).toFixed(1);\n        return `<tr>\n          <td><span class=\"team-cell\"><img class=\"team-logo\" src=\"${teamLogo(t.team)}\" alt=\"${t.team} logo\"><strong>${t.team}</strong></span></td>\n          <td>${t.w}-${t.l}${t.t ? '-' + t.t : ''}</td>\n          <td>${t.games}</td>\n          <td>${pct}%</td>\n          <td>${t.pf}-${t.pa}</td>\n        </tr>`;\n      }).join('')}\n    </tbody>\n  </table></div>`;\n}\n\nfunction normalizeSearch(query) {\n  return String(query || '').toLowerCase().trim().replace(/\\s+/g, ' ');\n}\n\nfunction gameMatchesSearch(g, query) {\n  if (!query) return true;\n  const q = normalizeSearch(query);\n  const opponent = g.opponent.toLowerCase();\n  const round = g.round.toLowerCase();\n  const year = String(g.year);\n  const combined = `${opponent} ${round} ${year}`;\n  return year.includes(q) || opponent.includes(q) || round.includes(q) || combined.includes(q);\n}\n\nfunction seasonSearchHit(year, query) {\n  if (!query) return true;\n  return (seasons[year] || []).some(g => gameMatchesSearch(g, query)) || String(year).includes(normalizeSearch(query));\n}\n\nfunction applyViewFilter(arr) {\n  if (state.filterMode === 'regular') return arr.filter(g => !g.isPlayoff);\n  if (state.filterMode === 'playoffs') return arr.filter(g => g.isPlayoff);\n  return arr;\n}\n\nfunction filteredSeasonGames(year) {\n  let arr = applyViewFilter([...(seasons[year] || [])]);\n  if (state.search) {\n    arr = arr.filter(g => gameMatchesSearch(g, state.search));\n  }\n  return arr;\n}\n\nfunction searchMatchedGames() {\n  let arr = applyViewFilter([...ALL_GAMES]);\n  if (state.search) {\n    arr = arr.filter(g => gameMatchesSearch(g, state.search));\n  }\n  return arr;\n}\n\nfunction renderSeasonStrip() {\n  const wrap = document.getElementById('seasonStrip');\n  wrap.innerHTML = YEARS\n    .filter(y => seasonSearchHit(String(y), state.search))\n    .map(y => {\n      const sum = seasonSummary(String(y));\n      const record = `${sum.reg.w}-${sum.reg.l}${sum.reg.t ? '-' + sum.reg.t : ''}`;\n      const active = String(y) === state.selectedYear ? 'active' : '';\n      const playoffText = sum.post.games ? `${sum.post.w}-${sum.post.l} ` : '';\n      return `<button class=\"season-btn ${active}\" data-year=\"${y}\">\n        <span class=\"year\">${y}</span>\n        <span class=\"mini\">${record} • ${playoffText}<span class=\"mini-playoff-dot ${sum.post.games ? 'on' : ''}\"></span></span>\n        <span class=\"mini-meter\"><span class=\"mini-meter-fill\" style=\"width:${sum.winPct}%\"></span></span>\n      </button>`;\n    }).join('');\n\n  [...wrap.querySelectorAll('.season-btn')].forEach(btn => {\n    btn.addEventListener('click', () => {\n      state.selectedYear = btn.dataset.year;\n      state.selectedMatchIndex = null;\n      state.isHistorical = false;\n      render();\n    });\n  });\n}\n\nfunction renderSeasonTopStats(year) {\n  const sum = seasonSummary(year);\n  const cards = [\n    { label: 'Regular Season', value: `${sum.reg.w}-${sum.reg.l}${sum.reg.t ? '-' + sum.reg.t : ''}`, color: '#0C2340' },\n    { label: 'Playoffs', value: sum.post.games ? `${sum.post.w}-${sum.post.l}` : '—', color: '#4B92DB' },\n    { label: 'Win %', value: `${sum.winPct}%`, color: Number(sum.winPct) >= 50 ? '#27ae60' : '#e74c3c' },\n    { label: 'Points For', value: sum.all.pf, color: '#F2F8FF' },\n    { label: 'Points Against', value: sum.all.pa, color: '#BFD0E5' },\n    { label: 'Point Diff', value: sum.pointDiff > 0 ? `+${sum.pointDiff}` : sum.pointDiff, color: sum.pointDiff >= 0 ? '#27ae60' : '#e74c3c' }\n  ];\n\n  document.getElementById('seasonStatsGrid').innerHTML = cards.map((c, i) => {\n    const widths = [Math.max(8, (sum.reg.w / Math.max(1, sum.all.games)) * 100), sum.post.games ? (sum.post.w / Math.max(1, sum.post.games)) * 100 : 10, Number(sum.winPct), Math.min(100, (sum.all.pf / 600) * 100), Math.min(100, (sum.all.pa / 600) * 100), Math.min(100, (Math.abs(sum.pointDiff) / 250) * 100)];\n    return `\n    <div class=\"stat-card ${i===0 ? 'active-stat' : ''}\" title=\"${c.label}\">\n      <div class=\"stat-label\">${c.label}</div>\n      <div class=\"stat-value\" style=\"color:${c.color}\">${c.value}</div>\n      \n    </div>\n  `}).join('');\n}\n\n\nfunction seasonStreakText(year) {\n  const games = seasonGames(year);\n  if (!games.length) return 'No streak';\n  let bestType = games[0].result, bestLen = 1, curType = games[0].result, curLen = 1;\n  for (let i = 1; i < games.length; i++) {\n    if (games[i].result === curType) curLen++;\n    else { curType = games[i].result; curLen = 1; }\n    if (curLen > bestLen) { bestLen = curLen; bestType = curType; }\n  }\n  return `${bestLen}-game ${bestType === 'W' ? 'win' : bestType === 'L' ? 'loss' : 'tie'} streak`;\n}\n\nfunction renderSeasonInfo(year) {\n  if (state.search) {\n    const matches = searchMatchedGames();\n    const wins = matches.filter(g => g.result === 'W').length;\n    const losses = matches.filter(g => g.result === 'L').length;\n    const ties = matches.filter(g => g.result === 'T').length;\n    const pf = matches.reduce((sum, g) => sum + g.ravensScore, 0);\n    const pa = matches.reduce((sum, g) => sum + g.oppScore, 0);\n    document.getElementById('seasonTitle').textContent = `Search Results: ${state.search}`;\n    document.getElementById('seasonSummaryLine').textContent =\n      `${matches.length} matching games across all seasons • ${wins}-${losses}${ties ? '-' + ties : ''} record`;\n    document.getElementById('seasonMeta').innerHTML = `\n      <div class=\"chip\">Search filter: ${state.search}</div>\n      <div class=\"chip\">Scope: all seasons</div>\n      <div class=\"chip\">View: ${state.filterMode === 'all' ? 'all games' : state.filterMode === 'regular' ? 'regular season only' : 'playoffs only'}</div>\n      <div class=\"chip\">Points: ${pf}-${pa}</div>\n    `;\n    return;\n  }\n  const sum = seasonSummary(year);\n  document.getElementById('seasonTitle').textContent = `${year} ${SEASON_EXTRA_DATA[String(year)]?.team_name || TEAM_CONFIG.teamName}`;\n  document.getElementById('seasonSummaryLine').textContent =\n    `${sum.all.games} total games • ${sum.reg.w}-${sum.reg.l}${sum.reg.t ? '-' + sum.reg.t : ''} regular season${sum.post.games ? ` • ${sum.post.w}-${sum.post.l} playoffs` : ''}`;\n  document.getElementById('seasonMeta').innerHTML = `\n    <div class=\"chip\">Search filter: ${state.search || 'none'}</div>\n    <div class=\"chip\">View: ${state.filterMode === 'all' ? 'all games' : state.filterMode === 'regular' ? 'regular season only' : 'playoffs only'}</div>\n    <div class=\"chip\">Season win rate: ${sum.winPct}%</div>\n    <div class=\"chip\">Scoring margin: ${sum.pointDiff > 0 ? '+' + sum.pointDiff : sum.pointDiff}</div>\n  `;\n}\n\nfunction renderMatches(year) {\n  const usingSearchResults = Boolean(state.search);\n  const games = usingSearchResults ? searchMatchedGames() : filteredSeasonGames(year);\n  if (!games.length) {\n    const searchLabel = state.search ? `\"${state.search}\"` : 'that search';\n    const filterLabel = state.filterMode === 'playoffs' ? 'playoff games' : state.filterMode === 'regular' ? 'regular-season games' : 'games';\n    document.getElementById('matchesWrap').innerHTML = usingSearchResults\n      ? emptyStateHTML({\n          kicker: 'Search miss',\n          title: `No ${currentTeamLabel()} games match ${searchLabel}.`,\n          description: 'Try a broader opponent, round, or year search, or clear the search to jump back into the full archive.',\n          actions: [\n            { action: 'clear-search', label: 'Clear search' },\n            { action: 'latest-season', label: 'Latest season' }\n          ]\n        })\n      : emptyStateHTML({\n          kicker: 'Filter miss',\n          title: `No ${filterLabel} found for ${year}.`,\n          description: 'This season does not have anything inside the current filter. Switch back to all games or jump to the latest season.',\n          actions: [\n            { action: 'show-all-games', label: 'Show all games' },\n            { action: 'latest-season', label: 'Latest season' }\n          ]\n        });\n    return;\n  }\n  let html = `<table>\n    <thead><tr>${usingSearchResults ? '<th>Year</th>' : ''}<th>Round</th><th>Opponent</th><th>Loc</th><th>TEN</th><th>OPP</th><th>Margin</th><th>Result</th></tr></thead><tbody>`;\n  games.forEach(g => {\n    const margin = g.ravensScore - g.oppScore;\n    const selected = state.selectedMatchIndex === g._index ? 'selected' : '';\n    const externalLink = matchLinkFor(g);\n    html += `<tr class=\"match-row row-${g.result === 'W' ? 'win' : g.result === 'L' ? 'loss' : 'tie'} ${selected} ${externalLink ? 'featured-game' : ''}\" data-index=\"${g._index}\" data-game-key=\"${g.year}|${g.round}|${g.opponent}\">\n      ${usingSearchResults ? `<td><strong>${g.year}</strong></td>` : ''}\n      <td>${g.round}${g.isPlayoff ? '<span class=\"tag\">Playoffs</span>' : ''}${externalLink ? '<span class=\"live-link\">Summary</span>' : ''}</td>\n      <td><span class=\"team-cell\"><img class=\"team-logo\" src=\"${teamLogo(g.opponent)}\" alt=\"${g.opponent} logo\"><strong>${g.opponent}</strong></span></td>\n      <td>${g.location === 'Home' ? '<span class=\"purple\">HOME</span>' : '<span class=\"muted\">AWAY</span>'}</td>\n      <td><strong>${g.ravensScore}</strong></td>\n      <td class=\"muted\">${g.oppScore}</td>\n      <td class=\"${margin > 0 ? 'green' : margin < 0 ? 'red' : 'muted'}\"><strong>${margin > 0 ? '+' + margin : margin}</strong></td>\n      <td><span class=\"result-badge result-${g.result}\">${g.result}</span></td>\n    </tr>`;\n  });\n  html += `</tbody></table>`;\n  document.getElementById('matchesWrap').innerHTML = html;\n  [...document.querySelectorAll('.match-row')].forEach(row => {\n    row.addEventListener('mouseenter', () => {\n      document.querySelectorAll('.match-row').forEach(r => {\n        if (r !== row && Number(r.dataset.index) !== state.selectedMatchIndex) r.classList.remove('selected');\n      });\n      row.classList.add('selected');\n    });\n    row.addEventListener('mouseleave', () => {\n      if (Number(row.dataset.index) !== state.selectedMatchIndex) row.classList.remove('selected');\n    });\n    row.addEventListener('click', () => {\n      const index = Number(row.dataset.index);\n      const pickedGame = ALL_GAMES[index];\n      state.selectedMatchIndex = index;\n      if (pickedGame) state.selectedYear = String(pickedGame.year);\n      document.querySelectorAll('.match-row.selected').forEach(r => {\n        if (r !== row) r.classList.remove('selected');\n      });\n      row.classList.add('selected');\n      row.classList.add('flash-row');\n      setTimeout(() => row.classList.remove('flash-row'), 900);\n      requestAnimationFrame(() => openMatch(index));\n    });\n  });\n}\n\n\nconst TEAM_META = {\n  ravens:{abbr:'BAL', bg:'#4B92DB', fg:'#0C2340'},\n  steelers:{abbr:'PIT', bg:'#101010', fg:'#f3c631'},\n  bengals:{abbr:'CIN', bg:'#fb4f14', fg:'#111111'},\n  browns:{abbr:'CLE', bg:'#311d00', fg:'#ff7f26'},\n  titans:{abbr:'TEN', bg:'#4b92db', fg:'#ffffff'},\n  jaguars:{abbr:'JAX', bg:'#006778', fg:'#d7a22a'},\n  oilers:{abbr:'HOU', bg:'#7dcad3', fg:'#15364a'},\n  texans:{abbr:'HOU', bg:'#03202f', fg:'#c8102e'},\n  patriots:{abbr:'NE', bg:'#002244', fg:'#c60c30'},\n  jets:{abbr:'NYJ', bg:'#125740', fg:'#ffffff'},\n  bills:{abbr:'BUF', bg:'#00338d', fg:'#c60c30'},\n  dolphins:{abbr:'MIA', bg:'#008e97', fg:'#f58220'},\n  colts:{abbr:'IND', bg:'#013369', fg:'#ffffff'},\n  chiefs:{abbr:'KC', bg:'#e31837', fg:'#ffffff'},\n  broncos:{abbr:'DEN', bg:'#fb4f14', fg:'#002244'},\n  chargers:{abbr:'LAC', bg:'#0080c6', fg:'#ffc20e'},\n  raiders:{abbr:'LV', bg:'#111111', fg:'#c4c8cb'},\n  seahawks:{abbr:'SEA', bg:'#002244', fg:'#69be28'},\n  rams:{abbr:'LAR', bg:'#003594', fg:'#ffd100'},\n  cardinals:{abbr:'ARI', bg:'#97233f', fg:'#ffffff'},\n  niners:{abbr:'SF', bg:'#aa0000', fg:'#d3bc8d'},\n  '49ers':{abbr:'SF', bg:'#aa0000', fg:'#d3bc8d'},\n  giants:{abbr:'NYG', bg:'#0b2265', fg:'#a71930'},\n  eagles:{abbr:'PHI', bg:'#004c54', fg:'#ffffff'},\n  cowboys:{abbr:'DAL', bg:'#041e42', fg:'#869397'},\n  commanders:{abbr:'WSH', bg:'#5a1414', fg:'#ffb612'},\n  redskins:{abbr:'WSH', bg:'#5a1414', fg:'#ffb612'},\n  bears:{abbr:'CHI', bg:'#0b162a', fg:'#c83803'},\n  lions:{abbr:'DET', bg:'#0076b6', fg:'#b0b7bc'},\n  packers:{abbr:'GB', bg:'#203731', fg:'#ffb612'},\n  vikings:{abbr:'MIN', bg:'#4f2683', fg:'#ffc62f'},\n  falcons:{abbr:'ATL', bg:'#a71930', fg:'#111111'},\n  panthers:{abbr:'CAR', bg:'#0085ca', fg:'#101820'},\n  saints:{abbr:'NO', bg:'#101820', fg:'#d3bc8d'},\n  buccaneers:{abbr:'TB', bg:'#d50a0a', fg:'#ff7900'}\n};\n\nfunction normalizeTeamName(name) {\n  return String(name || '').toLowerCase().trim().replace(/\\s+/g, ' ').replace(/\\.$/,'');\n}\nfunction teamMeta(name) {\n  const n = normalizeTeamName(name);\n  return TEAM_META[n] || {abbr: String(name || '?').slice(0,3).toUpperCase(), bg: TEAM_CONFIG.primaryColor, fg: TEAM_CONFIG.textOnDark};\n}\nfunction fallbackLogoDataUri(name) {\n  const raw = String(name || '?').trim();\n  const label = (raw.match(/[A-Za-z0-9]+/g) || ['?']).slice(0, 3).map((part) => part[0]).join('').slice(0, 3).toUpperCase() || '?';\n  const bg = encodeURIComponent(TEAM_CONFIG.primaryColor || '#1f2937');\n  const fg = encodeURIComponent(TEAM_CONFIG.textOnDark || '#ffffff');\n  const ring = encodeURIComponent(TEAM_CONFIG.secondaryColor || '#cbd5e1');\n  const svg = `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" rx=\"18\" fill=\"${bg}\"/><rect x=\"3\" y=\"3\" width=\"58\" height=\"58\" rx=\"15\" fill=\"none\" stroke=\"${ring}\" stroke-width=\"3\"/><text x=\"32\" y=\"39\" text-anchor=\"middle\" font-family=\"Arial, sans-serif\" font-size=\"24\" font-weight=\"700\" fill=\"${fg}\">${label}</text></svg>`;\n  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;\n}\nfunction teamLogo(name) {\n  const key = normalizeTeamName(name);\n  return TEAM_LOGO_MAP[key] || TEAM_LOGO_MAP[String(name || '').trim()] || fallbackLogoDataUri(name);\n}\nfunction teamPageUrl(teamName, params = {}) {\n  if (typeof TEAM_PAGE_MAP === 'undefined') return '';\n  const key = normalizeTeamName(teamName);\n  const page = TEAM_PAGE_MAP[key] || TEAM_PAGE_MAP[String(teamName || '').trim()] || '';\n  if (!page) return '';\n  const url = new URL(page, document.baseURI);\n  Object.entries(params).forEach(([paramKey, value]) => {\n    if (value !== null && value !== undefined && String(value).trim()) {\n      url.searchParams.set(paramKey, String(value));\n    }\n  });\n  return url.toString();\n}\nfunction compareSearchQueryFor(game) {\n  const teamLabel = typeof TEAM_CONFIG !== 'undefined' ? (TEAM_CONFIG.shortName || TEAM_CONFIG.teamName || 'Ravens') : 'Ravens';\n  return `vs ${teamLabel} ${game.year}${game.isPlayoff ? ' playoffs' : ''}`;\n}\nfunction leagueWideSearchUrlFor(game) {\n  const teamLabel = typeof TEAM_CONFIG !== 'undefined' ? (TEAM_CONFIG.shortName || TEAM_CONFIG.teamName || 'Ravens') : 'Ravens';\n  const query = `${teamLabel} vs ${game.opponent} ${game.year} ${game.round}`;\n  return `https://www.statmuse.com/nfl/ask?q=${encodeURIComponent(query)}`;\n}\nfunction applyUrlStateFromLocation() {\n  const params = new URLSearchParams(window.location.search);\n  const searchParam = String(params.get('search') || '').trim();\n  const yearParam = String(params.get('year') || '').trim();\n  const viewParam = String(params.get('view') || '').trim();\n\n  if (searchParam) {\n    state.search = searchParam;\n    state.isHistorical = false;\n  }\n  if (yearParam && YEARS.includes(Number(yearParam))) {\n    state.selectedYear = yearParam;\n  }\n  if (['all', 'regular', 'playoffs'].includes(viewParam)) {\n    state.filterMode = viewParam;\n  }\n\n  const searchInput = document.getElementById('seasonSearch');\n  if (searchInput) searchInput.value = state.search;\n  document.querySelectorAll('.toggle').forEach((btn) => {\n    btn.classList.toggle('active', btn.dataset.view === state.filterMode);\n  });\n}\n\n\nfunction formatRecord(games) {\n  const wins = games.filter(g => g.result === 'W').length;\n  const losses = games.filter(g => g.result === 'L').length;\n  const ties = games.filter(g => g.result === 'T').length;\n  return `${wins}-${losses}${ties ? '-' + ties : ''}`;\n}\n\nfunction lastGamesForm(games, count = 5) {\n  return games.slice(-count).map(g => g.result).join(' • ') || '—';\n}\n\nfunction renderSeasonExtra(year) {\n  const host = document.getElementById('seasonExtra');\n  const extra = SEASON_EXTRA_DATA[year];\n  const sum = seasonSummary(year);\n  const cleanRecord = extra?.record ? String(extra.record).replace(/^Record:\\s*/, '').replace(':','-') : `${sum.reg.w}-${sum.reg.l}${sum.reg.t ? '-' + sum.reg.t : ''}`;\n  const seasonGamesList = seasonGames(year);\n  const bestOpponentGame = [...seasonGamesList].sort((a,b) => (b.ravensScore-b.oppScore) - (a.ravensScore-a.oppScore))[0];\n  const outcome = seasonOutcomeLabel(year);\n\n  const bestOffenseGame = [...seasonGamesList].sort((a,b) => b.ravensScore - a.ravensScore)[0];\n  const bestDefenseGame = [...seasonGamesList].sort((a,b) => a.oppScore - b.oppScore)[0];\n  const closestGame = [...seasonGamesList].sort((a,b) => Math.abs(a.ravensScore-a.oppScore) - Math.abs(b.ravensScore-b.oppScore))[0];\n  const homeGames = seasonGamesList.filter(g => g.location === 'Home');\n  const awayGames = seasonGamesList.filter(g => g.location !== 'Home');\n\n  let html = `\n    <div class=\"panel-note\" style=\"margin-bottom:10px\"></div>\n    <div class=\"season-insight-grid\">\n      <div class=\"insight-pill\"><span>Best Offense</span><strong>${bestOffenseGame ? `${bestOffenseGame.ravensScore} pts vs ${bestOffenseGame.opponent}` : '—'}</strong><em>${bestOffenseGame ? bestOffenseGame.round : ''}</em></div>\n      <div class=\"insight-pill\"><span>Best Defense</span><strong>${bestDefenseGame ? `${bestDefenseGame.oppScore} pts allowed vs ${bestDefenseGame.opponent}` : '—'}</strong><em>${bestDefenseGame ? bestDefenseGame.round : ''}</em></div>\n      <div class=\"insight-pill\"><span>Closest Finish</span><strong>${closestGame ? `${closestGame.ravensScore}-${closestGame.oppScore} vs ${closestGame.opponent}` : '—'}</strong><em>${closestGame ? closestGame.round : ''}</em></div>\n      <div class=\"insight-pill\"><span>Home Record</span><strong>${formatRecord(homeGames)}</strong><em>${homeGames.length} home games</em></div>\n      <div class=\"insight-pill\"><span>Away Record</span><strong>${formatRecord(awayGames)}</strong><em>${awayGames.length} away games</em></div>\n      <div class=\"insight-pill\"><span>Last 5 Form</span><strong>${lastGamesForm(seasonGamesList, 5)}</strong><em>${seasonStreakText(year)}</em></div>\n    </div>\n    <div class=\"season-extra-grid\" style=\"margin-bottom:16px\">\n      <div class=\"extra-card\"><span>Record</span><strong>${cleanRecord}</strong></div>\n      <div class=\"extra-card\"><span>Division</span><strong>${extra?.division || '—'}</strong></div>\n      <div class=\"extra-card\"><span>Division Rank</span><strong>${extra?.division_rank ? `#${extra.division_rank}` : '—'}</strong></div>\n      <div class=\"extra-card\"><span>Coach</span><strong>${seasonCoach(year)}</strong></div>\n      <div class=\"extra-card\"><span>Season Finish</span><strong>${outcome}</strong></div>\n      <div class=\"extra-card\"><span>Win Rate</span><strong>${sum.winPct}%</strong></div>\n      <div class=\"extra-card\"><span>Point Diff</span><strong>${sum.pointDiff > 0 ? '+' + sum.pointDiff : sum.pointDiff}</strong></div>\n      <div class=\"extra-card\"><span>PF / PA</span><strong>${sum.all.pf} / ${sum.all.pa}</strong></div>\n      <div class=\"extra-card\"><span>Playoff Record</span><strong>${sum.post.games ? `${sum.post.w}-${sum.post.l}` : '—'}</strong></div>\n      <div class=\"extra-card\"><span>Best Margin</span><strong>${bestOpponentGame ? `${bestOpponentGame.round} vs ${bestOpponentGame.opponent}` : '—'}</strong></div>\n    </div>\n    <div class=\"panel-note\" style=\"margin-bottom:10px\">Season game flow</div>\n    ${winLossTimelineHTML(seasonGamesList)}\n  `;\n\n  if (extra && extra.stats && Object.keys(extra.stats).length) {\n    html += `<div class=\"panel-note\" style=\"margin-bottom:10px\">Imported season stats</div><div class=\"season-extra-grid\" style=\"margin-bottom:18px\">`;\n    Object.entries(extra.stats).forEach(([k,v]) => {\n      html += `<div class=\"extra-card\"><span>${k}</span><strong>${String(v).toUpperCase() === 'TBD' ? '<span class=\"tbd-badge\">TBD</span>' : v}</strong></div>`;\n    });\n    html += `</div>`;\n  } else {\n    html += `<div class=\"panel-note\" style=\"margin-bottom:14px\"></div>`;\n  }\n\n  html += `<div class=\"panel-note\" style=\"margin:14px 0 10px\"></div>${playoffBracketHTML(year)}`;\n\n  if (extra && extra.standings && extra.standings.length) {\n    html += `<div class=\"panel-note\" style=\"margin:14px 0 10px\"></div><div class=\"table-wrap\"><table><thead><tr><th>Division Team</th><th>W</th><th>L</th><th>T</th><th>PCT</th></tr></thead><tbody>`;\n    extra.standings.forEach(row => {\n      const isRavens = String(row.team).toLowerCase().includes('ravens');\n      html += `<tr style=\"${isRavens ? 'background:rgba(12,35,64,0.10)' : ''}\">\n        <td><span class=\"team-cell\"><img class=\"team-logo\" src=\"${teamLogo(row.team)}\" alt=\"${row.team} logo\"><strong style=\"color:${isRavens ? '#0C2340' : '#F2F8FF'}\">${row.team}</strong></span></td>\n        <td>${row.W ?? '—'}</td><td>${row.L ?? '—'}</td><td>${row.T ?? '—'}</td><td>${row.PCT ?? '—'}</td>\n      </tr>`;\n    });\n    html += `</tbody></table></div>`;\n  } else {\n    html += `<div class=\"panel-note\">No division standings were imported for this season.</div>`;\n  }\n  host.innerHTML = html;\n}\n\nfunction openMatch(index) {\n  const g = ALL_GAMES[index];\n  const modal = document.getElementById('matchModal');\n  const detailKey = [g.year, g.round.trim(), g.opponent, g.location, `${g.ravensScore}-${g.oppScore}`].join(\"|\");\n  const detail = MATCH_DETAILS[detailKey] || null;\n  const seasonBlock = SEASON_EXTRA_DATA[String(g.year)] || null;\n  const margin = g.ravensScore - g.oppScore;\n\n  const externalLink = matchLinkFor(g);\n  document.getElementById('modalTitle').textContent = `${g.year} • ${g.round}`;\n  document.getElementById('modalSub').textContent = `${g.isPlayoff ? 'Playoff game' : 'Regular season game'} • ${g.location}${externalLink ? ' • Includes linked DAZN summary' : ''} • Tap outside this panel or the × button to close`;\n\n  let comparisonHtml = '';\n  if (detail && detail.teamStats && detail.teamStats.length) {\n    comparisonHtml = `<div class=\"mini-panel\"><h3>Team Stats</h3><div class=\"inside\">\n      <table class=\"compare-table\"><tbody>${detail.teamStats.map(row => `\n        <tr class=\"${row.stat === 'Possession' ? 'compare-row-possession' : ''}\"><td><span class=\"compare-value${row.stat === 'Possession' ? ' compare-value-time' : ''}\">${row.left}</span></td><td>${detail.leftTeam}</td><td>${row.stat}</td><td>${detail.rightTeam}</td><td><span class=\"compare-value${row.stat === 'Possession' ? ' compare-value-time' : ''}\">${row.right}</span></td></tr>\n      `).join('')}</tbody></table>\n    </div></div>`;\n  } else {\n    comparisonHtml = `<div class=\"mini-panel\"><h3>Team Stats</h3><div class=\"inside\"><div class=\"muted\">No detailed match stat sheet has been imported for this game yet. Right now, the workbook only includes detailed game sheets for the 1996 season.</div></div></div>`;\n  }\n\n  let seasonSnippet = '';\n  if (seasonBlock && seasonBlock.stats && Object.keys(seasonBlock.stats).length) {\n    seasonSnippet = `<div class=\"mini-panel season-snapshot-panel\"><h3>Season Snapshot</h3><div class=\"inside\"><div class=\"season-extra-grid season-snapshot-grid\">\n      ${Object.entries(seasonBlock.stats).slice(0, 8).map(([k,v]) => `<div class=\"extra-card\"><span>${k}</span><strong>${String(v).toUpperCase() === 'TBD' ? '<span class=\"tbd-badge\">TBD</span>' : v}</strong></div>`).join('')}\n    </div></div></div>`;\n  } else {\n    const sum = seasonSummary(String(g.year));\n    seasonSnippet = `<div class=\"mini-panel season-snapshot-panel\"><h3>Season Snapshot</h3><div class=\"inside\"><div class=\"season-extra-grid season-snapshot-grid\">\n      <div class=\"extra-card\"><span>Record</span><strong>${sum.reg.w}-${sum.reg.l}${sum.reg.t ? '-' + sum.reg.t : ''}</strong></div>\n      <div class=\"extra-card\"><span>Points For</span><strong>${sum.all.pf}</strong></div>\n      <div class=\"extra-card\"><span>Points Against</span><strong>${sum.all.pa}</strong></div>\n      <div class=\"extra-card\"><span>Playoffs</span><strong>${sum.post.games ? `${sum.post.w}-${sum.post.l}` : '—'}</strong></div>\n    </div></div></div>`;\n  }\n\n  document.getElementById('modalBody').innerHTML = `\n    <div class=\"scoreline\">\n      <div class=\"team-box\">\n        <div class=\"score-team-head\">\n          <img class=\"score-team-logo\" src=\"${teamLogo(TEAM_CONFIG.shortName)}\" alt=\"Titans logo\">\n          <div class=\"score-team-name\">Titans</div>\n        </div>\n        <div class=\"score\">${g.ravensScore}</div>\n        <div class=\"meta\">${g.location} • ${margin > 0 ? 'Won by ' + margin : margin < 0 ? 'Lost by ' + Math.abs(margin) : 'Tie game'}</div>\n      </div>\n      <div class=\"versus\">VS</div>\n      <div class=\"team-box\">\n        <div class=\"score-team-head\">\n          <img class=\"score-team-logo\" src=\"${teamLogo(g.opponent)}\" alt=\"${g.opponent} logo\">\n          <div class=\"score-team-name\">${g.opponent}</div>\n        </div>\n        <div class=\"score\">${g.oppScore}</div>\n        <div class=\"meta\">${g.isPlayoff ? 'Postseason' : 'Regular season'} • <span class=\"${g.result === 'W' ? 'green' : g.result === 'L' ? 'red' : 'muted'}\">${g.result}</span></div>\n      </div>\n    </div>\n    <div class=\"season-meta\" style=\"margin-bottom:16px\">\n      <div class=\"chip\">Round: ${g.round}</div>\n      <div class=\"chip\">Location: ${g.location}</div>\n      <div class=\"chip\">Result: ${g.result}</div>\n      <div class=\"chip\">Final: ${g.ravensScore}-${g.oppScore}</div>\n    </div>\n    ${externalLink ? `<div class=\"modal-link-row\"><a class=\"modal-link-btn\" href=\"${externalLink.url}\" target=\"_blank\" rel=\"noopener noreferrer\">${externalLink.label}</a></div>` : ''}\n    <div class=\"modal-actions\">\n      <button class=\"modal-nav-btn\" id=\"prevMatchBtn\">← Previous Game</button>\n      <button class=\"modal-nav-btn\" id=\"nextMatchBtn\">Next Game →</button>\n    </div>\n    <div class=\"detail-grid\">${comparisonHtml}${seasonSnippet}</div>\n    <div class=\"detail-grid\" style=\"margin-top:16px;\">\n      <div class=\"mini-panel\">\n        <h3>Win Probability</h3>\n        <div class=\"inside\">\n          <div class=\"winprob-track\">\n            ${buildWinProbability(g).map(row => `\n              <div class=\"winprob-row\">\n                <div>${row.label}</div>\n                <div class=\"winprob-bar\"><div class=\"winprob-fill\" style=\"width:${row.value}%;\"></div></div>\n                <div>${row.value}%</div>\n              </div>\n            `).join('')}\n          </div>\n          <div class=\"muted\" style=\"margin-top:10px;\">Fast visual model for game momentum. It is a lightweight estimate based on the final score swing, not official play-by-play win probability.</div>\n        </div>\n      </div>\n      <div class=\"mini-panel\">\n        <h3>Similar Games</h3>\n        <div class=\"inside\">\n          <div class=\"similar-grid\">\n            ${similarGamesFor(g).map(sim => `\n              <div class=\"similar-card\">\n                <span>${sim.year} • ${sim.round}</span>\n                <strong>Titans ${sim.ravensScore}-${sim.oppScore} ${sim.opponent}</strong>\n                <button class=\"hero-btn\" data-sim-game=\"${sim._index}\">Open in season explorer</button>\n              </div>\n            `).join('')}\n          </div>\n        </div>\n      </div>\n    </div>\n  `;\n\n  document.querySelectorAll('[data-sim-game]').forEach(btn => {\n    btn.addEventListener('click', () => openMatch(Number(btn.dataset.simGame)));\n  });\n\n  const yearGames = filteredSeasonGames(String(g.year));\n  const currentPos = yearGames.findIndex(x => x._index === index);\n  const prev = yearGames[currentPos - 1] || null;\n  const next = yearGames[currentPos + 1] || null;\n  const prevBtn = document.getElementById('prevMatchBtn');\n  const nextBtn = document.getElementById('nextMatchBtn');\n  if (prevBtn) {\n    prevBtn.disabled = !prev;\n    prevBtn.addEventListener('click', () => {\n      if (!prev) return;\n      state.selectedMatchIndex = prev._index;\n      renderMatches(String(g.year));\n      openMatch(prev._index);\n    });\n  }\n  if (nextBtn) {\n    nextBtn.disabled = !next;\n    nextBtn.addEventListener('click', () => {\n      if (!next) return;\n      state.selectedMatchIndex = next._index;\n      renderMatches(String(g.year));\n      openMatch(next._index);\n    });\n  }\n\n  modal.classList.add('open');\n}\n\nfunction closeModal() {\n  document.getElementById('matchModal').classList.remove('open');\n}\n\n\nconst RIVALRY_DATA = {\"Colts\":{\"games\":56,\"record\":\"18-38\",\"recent\":[{\"date\":\"2025-10-26\",\"result\":\"L\",\"ravensScore\":14,\"teamScore\":14,\"oppScore\":38,\"displayDate\":\"10/26/2025\",\"location\":\"Away\",\"opponent\":\"Colts\",\"opponentCode\":\"IND\",\"passingYards\":\"259\",\"rushingYards\":\"113\",\"turnovers\":\"1\",\"firstDowns\":\"20\",\"possession\":\"34:21\",\"yardsPerPass\":\"6.8\",\"interceptionsThrown\":\"1\",\"fumblesLost\":\"0\",\"sacks\":\"4\",\"passAttempts\":\"38\",\"round\":\"Week 8\",\"year\":2025,\"isPlayoff\":false,\"totalYards\":\"372\",\"opponentTotalYards\":\"436\",\"totalPlays\":\"\",\"yardsPerPlay\":\"\",\"yardsPerRush\":\"\",\"punts\":\"\",\"penalties\":\"\",\"rushAttempts\":\"\",\"opponentPassingYards\":\"272\",\"opponentRushingYards\":\"164\",\"opponentTurnovers\":\"0\",\"opponentFirstDowns\":\"21\",\"opponentPassAttempts\":\"31\",\"opponentRushAttempts\":\"18\",\"opponentPunts\":\"4\",\"opponentPenalties\":\"3\",\"opponentSacks\":\"3\",\"opponentFumblesLost\":\"0\",\"opponentInterceptionsThrown\":\"0\",\"opponentTotal